// Swipe (getswipe.in) on the business's own API key: invoices and every other document, customers, vendors,
// products, payments, stock, subscriptions, e-way bills and GSTIN lookup. actions.json is generated by
// `bun scripts/openapi-actions.ts swipe`; expenses are missing from Swipe's spec but live, so they're by hand here.
// COVERAGE.md says what's left out.
import { z } from "zod";
import type { OwnApp } from "../index";
import { type Api, call, rest, specActions } from "../openapi";
import { events, receive, triggers, watch, wanted, webhookSetup } from "./triggers";

const api: Api = {
  name: "Swipe",
  base: "https://app.getswipe.in/api/partner",
  tokenHelp: "Swipe → Settings → API Integration",
  // a 401 FORBIDDEN is a working key whose plan can't do this, not a dead one
  deadToken: (status, body) => status === 401 && body?.error_code !== "FORBIDDEN",
  failed: (body) => (body?.success === false ? `${body.error_code ?? "error"}: ${body.message ?? "request rejected"}` : undefined),
};

const DATE = "DD-MM-YYYY, day first (e.g. 27-08-2026); ISO dates are rejected";
const hashId = z.string().min(1).describe("Swipe's hash_id for the expense, from list_expenses");
const page = {
  num_records: z.number().int().min(1).max(100).optional().describe("Rows per page, up to 100 (default 10)"),
  page: z.number().int().min(1).optional().describe("Page number, from 1"),
};

const expenses = {
  list_expenses: rest(
    api,
    "GET",
    "/v2/expense/list",
    "Expenses (rent, salaries, utilities: money out that isn't a purchase document) over a date range, with category, party, amounts and payment status. Each row has the hash_id the other expense actions take.",
    z.object({
      document_type: z.string().min(1).describe('Which expense documents; "purchase" for a recorded expense'),
      start_date: z.string().describe(`From, inclusive. ${DATE}`),
      end_date: z.string().describe(`To, inclusive. ${DATE}`),
      payment_status: z.string().optional().describe('"all" (default), "pending", "paid"…'),
      ...page,
    }),
  ),
  get_expense: rest(api, "GET", "/v2/expense/{hash_id}", "One expense in full: category, party, line items with tax, payments and what's pending. Read it before update_expense.", z.object({ hash_id: hashId })),
  update_expense: {
    description:
      "Change an existing expense and optionally attach receipts. There is no create: expenses are raised in the Swipe app. amount, document_date, items, party and payment_details are required every time, so read it with get_expense first and send it back changed. Attachments are added, not replaced.",
    input: z.object({
      hash_id: hashId,
      amount: z.number().describe("The total, tax included when with_tax is true"),
      document_date: z.string().describe(`The expense's date. ${DATE}`),
      items: z.array(z.record(z.string(), z.unknown())).min(1).describe("The lines, shaped like get_expense's (category, description, net_amount, tax, tax_amount, total_amount)"),
      party: z.record(z.string(), z.unknown()).describe("Who was paid, like get_expense's: {name, vendor_id, customer_id}"),
      payment_details: z.record(z.string(), z.unknown()).describe("How it was paid, like get_expense's: {amount, amount_paid, bank_id, notes}"),
      with_tax: z.boolean().optional().describe("Whether amount includes tax (default false)"),
      category: z.string().optional().describe('Kind of spend: "Rent", "Travel"…'),
      description: z.string().optional(),
      supplier_invoice_date: z.string().optional().describe(`The date on the supplier's own invoice. ${DATE}`),
      tds_id: z.number().int().optional().describe("TDS code from developers.getswipe.in/api-reference/tax-codes; -1 for none (default)"),
      attachments: z.array(z.any()).optional().describe('Receipts or bills to attach: [{"file": "/work/..."}]'),
    }),
    run: (i: Record<string, any>, key: string) => {
      // Swipe reads the expense from the query (its three objects as JSON text) and only the files from the body
      const input: Record<string, unknown> = { ...i, items: JSON.stringify(i.items), party: JSON.stringify(i.party), payment_details: JSON.stringify(i.payment_details) };
      const query = Object.keys(input).filter((k) => k !== "hash_id" && k !== "attachments" && input[k] !== undefined);
      const body = i.attachments?.length ? { kind: "form" as const, fields: [["attachments", "attachments"]] as [string, string][] } : undefined;
      return call(api, key, { method: "POST", path: "/v2/expense/{hash_id}", query, headers: [], body }, input);
    },
  },
  cancel_expense: rest(api, "DELETE", "/v2/expense/{hash_id}", "Cancel an expense. It stays on the books marked cancelled.", z.object({ hash_id: hashId })),
  get_expense_pdf: rest(api, "GET", "/v2/expense/pdf/{hash_id}", "Swipe's PDF of an expense (not the receipts attached to it).", z.object({ hash_id: hashId })),
};

// Swipe's webhook is a setting in its dashboard, not something an API can switch on, so the business has to paste
// the address in once. This is what to tell them, for this connection.
const setup = {
  get_webhook_setup: {
    description:
      "Where to paste Emplio's address in Swipe so Swipe's instant triggers (new_document, stock_moved…) work. Swipe takes a webhook only in its own dashboard and only one per company, so the owner does this once by hand; tell them the address and the two events to tick exactly as this answers. Swipe's polled triggers (new_invoice, invoice_paid, payment_received…) need none of this.",
    input: z.object({}),
    readOnly: true,
    run: async (_input: Record<string, unknown>, _key: string, connection?: string) => webhookSetup(connection),
  },
};

export const swipe: OwnApp = {
  app: "swipe",
  name: "Swipe",
  logo: "/logos/swipe.png",
  keyField: {
    label: "API key",
    help: "In Swipe: Settings → API Integration → generate a key (app.getswipe.in/user?tab=api_integration). A key works for the company it was made in.",
    placeholder: "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx",
  },
  // every account has a product list, even an empty one
  async check(key) {
    await call(api, key, { method: "GET", path: "/v2/product/list", query: ["num_records"], headers: [] }, { num_records: 1 });
  },
  actions: { ...(await specActions(new URL("./actions.json", import.meta.url), api)), ...expenses, ...setup },
  push: { events, triggers, wanted, receive, start: (_key, connection) => watch(connection) },
};
